-- Content corrections for sample data (ecological/cultural accuracy).
-- Each UPDATE only applies while the row still holds the original sample text,
-- so edits made in the admin panel are never overwritten.
UPDATE team_members SET short_bio_en = $wmc$Irarutu elder from Babo District and guardian of customary mangrove knowledge passed down over four generations.$wmc$, short_bio_id = $wmc$Tetua suku Irarutu dari Distrik Babo, penjaga pengetahuan adat tentang mangrove yang diwariskan empat generasi.$wmc$, bio_en = $wmc$Benas Wanda is a respected elder and traditional knowledge holder of the Irarutu people, whose customary lands lie along the southern shore of Bintuni Bay in Babo District. Raised in a fishing and sago-gathering family, he learned crab-trapping grounds, tidal navigation and the uses of mangrove plants from his father and grandfather. As the clan-appointed representative for conservation matters, he helps translate customary rules into co-management agreements, advises on seasonal harvest closures for mud crab, and makes sure research in Irarutu territory follows free, prior and informed consent.$wmc$, bio_id = $wmc$Benas Wanda adalah tetua dan pemegang pengetahuan adat yang dihormati dari suku Irarutu, yang wilayah adatnya membentang di pesisir selatan Teluk Bintuni, Distrik Babo. Tumbuh di keluarga nelayan dan peramu sagu, ia mempelajari lokasi tangkapan kepiting, navigasi pasang surut, dan kegunaan tumbuhan mangrove dari ayah dan kakeknya. Sebagai wakil marga untuk urusan konservasi, ia membantu menerjemahkan aturan adat ke dalam kesepakatan pengelolaan bersama, memberi masukan soal penutupan musiman penangkapan kepiting bakau, dan memastikan setiap riset di wilayah Irarutu mengikuti prinsip persetujuan atas dasar informasi di awal tanpa paksaan (PADIATAPA).$wmc$, updated_at = now() WHERE slug = 'pak-benas-wanda' AND bio_en LIKE '%Mairasi%';
--> statement-breakpoint
UPDATE team_members SET bio_en = $wmc$Dr. Resti Anggraini is a tropical ornithologist whose postdoctoral work focuses on migratory shorebirds using the mudflats of Bintuni Bay on the East Asian–Australasian Flyway. Trained at IPB University and the Cornell Lab of Ornithology, she runs the Center's monthly high-tide roost counts and a citizen-science bird monitoring programme with local schools. Her counts include the Endangered Far Eastern Curlew and large flocks of Whimbrel during southward migration, evidence used in the bay's proposed Ramsar nomination.$wmc$, bio_id = $wmc$Dr. Resti Anggraini adalah ornitolog tropis yang penelitian pascadoktoralnya berfokus pada burung pantai migran yang memanfaatkan dataran lumpur Teluk Bintuni di Jalur Terbang Asia Timur–Australasia. Lulusan IPB University dan Cornell Lab of Ornithology, ia menjalankan penghitungan bulanan burung di lokasi istirahat saat pasang tinggi serta program pemantauan burung berbasis sains warga bersama sekolah setempat. Hasil hitungannya mencatat Gajahan Timur yang berstatus Genting serta kawanan besar Gajahan Pengala saat migrasi ke selatan — bukti yang digunakan dalam usulan nominasi Ramsar teluk ini.$wmc$, expertise = ARRAY[$wmc$Ornithology$wmc$,$wmc$Migratory Shorebirds$wmc$,$wmc$Citizen Science$wmc$,$wmc$Flyway Conservation$wmc$]::text[], updated_at = now() WHERE slug = 'dr-resti-anggraini' AND bio_en LIKE '%Milky Stork%';
--> statement-breakpoint
UPDATE team_members SET role_en = $wmc$Ethnobiology Programme Lead$wmc$, role_id = $wmc$Ketua Program Etnobiologi$wmc$, updated_at = now() WHERE slug = 'prof-willem-kwai' AND role_en = 'Marine Ecology Expert';
--> statement-breakpoint
UPDATE team_members SET bio_en = $wmc$Desy Maramatua serves as the bridge between Hub Bintuni's research operations and the eight partner communities around Bintuni Bay. With a background in Community Development from Universitas Indonesia and training in fair-trade enterprise auditing, she has helped establish five women-led cooperatives producing value-added mangrove products such as Nypa palm sugar, Bruguiera (lindur) fruit flour and woven crafts. Her flagship programme, "Mangrove Mothers", trains women in sustainable harvesting, bookkeeping and direct-to-market sales. She also facilitates quarterly Community Conservation Forums where customary leaders co-design research priorities with the science team.$wmc$, bio_id = $wmc$Desy Maramatua menjembatani kegiatan riset Hub Bintuni dengan delapan komunitas mitra di sekitar Teluk Bintuni. Berlatar belakang Pembangunan Masyarakat dari Universitas Indonesia dan pelatihan audit usaha perdagangan adil, ia membantu mendirikan lima koperasi yang dipimpin perempuan yang menghasilkan produk mangrove bernilai tambah seperti gula nipah, tepung buah lindur (Bruguiera), dan kerajinan anyaman. Program andalannya, "Mama-Mama Mangrove", melatih perempuan dalam pemanenan berkelanjutan, pembukuan, dan penjualan langsung ke pasar. Ia juga memfasilitasi Forum Konservasi Masyarakat triwulanan, tempat para pemimpin adat merancang prioritas riset bersama tim sains.$wmc$, updated_at = now() WHERE slug = 'ibu-desy-maramatua' AND bio_en LIKE '%dried mangrove crab%';
--> statement-breakpoint
UPDATE publications SET title_en = $wmc$Carbon Stocks of Rhizophora apiculata Stands in the Bintuni Bay Estuary$wmc$, title_id = $wmc$Stok Karbon Tegakan Rhizophora apiculata di Muara Teluk Bintuni$wmc$, abstract_en = $wmc$Above-ground, root and soil carbon (to 1 m) were measured in 24 permanent plots across mature and regenerating Rhizophora apiculata stands. Mature stands held a mean total ecosystem carbon stock of about 1,050 Mg C ha⁻¹, roughly three-quarters of it in the soil — in line with published Indo-Pacific mangrove estimates and well above most terrestrial forests.$wmc$, abstract_id = $wmc$Karbon atas permukaan, akar, dan tanah (hingga kedalaman 1 m) diukur di 24 petak permanen pada tegakan Rhizophora apiculata dewasa dan yang sedang beregenerasi. Tegakan dewasa menyimpan rata-rata stok karbon ekosistem sekitar 1.050 Mg C ha⁻¹, kira-kira tiga perempatnya di dalam tanah — sejalan dengan estimasi mangrove Indo-Pasifik yang telah dipublikasikan dan jauh di atas sebagian besar hutan daratan.$wmc$, updated_at = now() WHERE slug = 'p1' AND abstract_en LIKE '%sequestration rates of 328%';
--> statement-breakpoint
UPDATE publications SET abstract_en = $wmc$An 18-month baseline survey recording 30 true mangrove species, 168 fish species, 112 bird species (including the Endangered Far Eastern Curlew) and 89 benthic macrofauna morphospecies across the 124,851 ha Teluk Bintuni Nature Reserve and adjacent estuaries.$wmc$, abstract_id = $wmc$Survei baseline selama 18 bulan yang mencatat 30 spesies mangrove sejati, 168 spesies ikan, 112 spesies burung (termasuk Gajahan Timur yang berstatus Genting), dan 89 morfospesies makrofauna bentik di Cagar Alam Teluk Bintuni seluas 124.851 ha beserta muara di sekitarnya.$wmc$, updated_at = now() WHERE slug = 'p2' AND abstract_en LIKE '%34 mangrove species%';
--> statement-breakpoint
UPDATE publications SET title_en = $wmc$Migratory Shorebirds on the Bintuni Mudflats: Stopover Use by Far Eastern Curlew and Whimbrel, 2023–2026$wmc$, title_id = $wmc$Burung Pantai Migran di Dataran Lumpur Bintuni: Pemanfaatan Lokasi Singgah oleh Gajahan Timur dan Gajahan Pengala, 2023–2026$wmc$, abstract_en = $wmc$Monthly high-tide roost counts at six sites recorded 14 shorebird species, with peak counts of about 1,200 birds during southward migration (September–November). Up to 38 Far Eastern Curlew (Numenius madagascariensis, Endangered) were counted, confirming the bay as a regular stopover on the East Asian–Australasian Flyway.$wmc$, abstract_id = $wmc$Penghitungan bulanan di enam lokasi istirahat saat pasang tinggi mencatat 14 spesies burung pantai, dengan puncak sekitar 1.200 ekor saat migrasi ke selatan (September–November). Hingga 38 ekor Gajahan Timur (Numenius madagascariensis, berstatus Genting) tercatat, menegaskan teluk ini sebagai lokasi singgah rutin di Jalur Terbang Asia Timur–Australasia.$wmc$, tags = ARRAY[$wmc$Ornithology$wmc$,$wmc$Shorebirds$wmc$,$wmc$Flyway$wmc$]::text[], image_url = $wmc$https://coresg-normal.trae.ai/api/ide/v1/text_to_image?prompt=Flock%20of%20migratory%20shorebirds%20curlews%20and%20whimbrels%20feeding%20on%20tidal%20mudflat%20in%20front%20of%20mangrove%20forest%2C%20West%20Papua%2C%20soft%20morning%20light&image_size=square$wmc$, updated_at = now() WHERE slug = 'p5' AND title_en LIKE 'Milky Stork%';
--> statement-breakpoint
UPDATE publications SET title_en = $wmc$Traditional Ecological Knowledge Compendium: Irarutu and Kuri Mangrove Knowledge$wmc$, title_id = $wmc$Kompilasi Pengetahuan Ekologi Tradisional: Pengetahuan Mangrove Suku Irarutu dan Kuri$wmc$, updated_at = now() WHERE slug = 'p6' AND title_en LIKE '%Mairasi%';
--> statement-breakpoint
UPDATE map_features SET description_en = $wmc$Viewing platform for herons, kingfishers and migratory shorebirds such as Whimbrel, best around low tide. (Sample data — illustrative location.)$wmc$, description_id = $wmc$Menara pengamatan untuk cangak, raja-udang, dan burung pantai migran seperti Gajahan Pengala, paling baik saat air surut. (Data contoh — lokasi ilustratif.)$wmc$, updated_at = now() WHERE slug = 'titik-pengamatan-burung' AND description_en LIKE '%milky stork%';
--> statement-breakpoint
UPDATE metrics SET value_en = $wmc$30$wmc$, value_id = $wmc$30$wmc$, label_en = $wmc$True Mangrove Species Recorded$wmc$, label_id = $wmc$Spesies Mangrove Sejati Tercatat$wmc$, updated_at = now() WHERE key = 'species_documented' AND value_en = '34';
